pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address oldOwner = c.owner();
        vm.prank(oldOwner);
        c.transferOwnership(newOwner);
        if (c.owner() == oldOwner) {
            vm.prank(oldOwner);
            try c.renounceOwnership() { assertTrue(false, "renounceOwnership should revert"); } catch { }
        } else {
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address currentOwner, address newOwner, address nonOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(nonOwner != address(0));
        vm.assume(currentOwner != nonOwner);

        // set owner to currentOwner
        vm.prank(address(c).balance > 0 ? address(this) : address(this));
        c.transferOwnership(currentOwner);

        // have nonOwner attempt transferOwnership
        vm.prank(nonOwner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        // the correct contract should revert (success=false) because nonOwner is not owner
        assertTrue(!success);
    }
}

